def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G where
  base := {a : G | ∃ h, h ∈ H ∧ a = x * h * x⁻¹}
  ⟨1, H.one_mem, λ h, h⁻¹ (H.inv_mem h.2), λ h₁ h₂, h₁ (H.mul_mem h₁.2 h₂.2)⟩

theorem t4 (φ : G →* H) (ψ : H →* K) (S : Subgroup G) :
    map (ψ.comp φ) S = map ψ (S.map φ)  := by
  rw [← map_eq_mul, map_eq_mul, map_map]; intro; apply Monoid.mul_eq_mul_iff (S.sub semigroup) (S.sub semigroup) (λ a b h b', h b' a}

lemma eq_bot_iff_card {G : Type*} [Group G] {H : Subgroup G} :
    H = ⊥ ↔ Nat.card H = 1  := by
  simpa [eq_bot_iff_forall, Nat.card_eq_one_iff_exists]
  constructor;
  · exact fun h => ⟨1, H.one_mem, fun x hx => by calc x = 1 := (h x hx)⟩;
  · exact fun ⟨y, -, hy'⟩ x hx => by calc x = y := hy' x hx; 1 = y := (hy' 1 H.one_mem).symm

lemma aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K   := by
  rw [← H.index_eq_card, H.index_mul_card, h', mul_comm] at ⊢;

